import {startFlowPlayback} from './flow-playback.js?v=speed-20261005';
import {buildInternet} from './internet-model.js?v=speed-20261005';
export function internetSurface(){return `<section class="internet-lab"><h2>ออกจากบ้าน สู่เครือข่ายทั่วโลก</h2><p>บ้าน → Fiber access → ISP → Peering/Transit → เครือข่ายบริการ → Social / CDN / Game</p><div class="internet-settings"><label>บริการ<select name="service"><option value="social">Social feed · บริการสมมติ</option><option value="cdn">รูป / วิดีโอจาก CDN</option><option value="game">เกมออนไลน์ · Session สมมติ</option></select></label><label>เส้นทาง<select name="route"><option value="peering">Peering ผ่าน IXP</option><option value="transit">ผ่าน Transit provider</option></select></label><label>ปัญหาที่จำลอง<select name="fault"><option value="none">เชื่อมต่อสำเร็จ</option><option value="gateway">ไม่มี Gateway</option><option value="dns">DNS ไม่พบชื่อ</option><option value="uplink">ISP uplink down</option></select></label></div><p>แผนผังสมมติ ไม่ใช่โครงข่ายจริงขององค์กรหรือผู้ให้บริการใด ไม่ระบุตำแหน่งภูมิศาสตร์จริง IP/โดเมนเป็นตัวอย่าง; สมมติ DHCP/ARP พร้อม, IPv4+NAT, ไม่จำลอง CGNAT, BGP convergence หรือ handshake ทุก Packet</p><div class="mechanism-stage is-3d internet-stage" aria-label="โลกเครือข่าย Internet สามมิติ"><div class="internet-fallback"></div></div><div class="internet-controls"><button class="button light" data-internet="prev">‹ ขั้นก่อน</button><button class="button" data-internet="play">▶ เล่นเส้นทาง</button><button class="button light" data-internet="next">ขั้นถัดไป ›</button><button class="button light" data-internet="reset">เริ่มใหม่</button><button class="button light" data-internet="view">รีเซ็ตมุมมอง</button><label>ขั้นตอน<input type="range" min="0" value="0" aria-label="ขั้นตอน Internet"></label></div><section class="internet-evidence" aria-live="polite"><p></p><h3></h3><div></div><dl></dl></section><p>ภารกิจ: เล่นจนคำตอบกลับถึง Computer จากนั้นเปลี่ยน Social เป็น CDN/เกม เปรียบเทียบปลายทางและ Protocol แล้วทดลอง DNS ผิดหรือ uplink down เพื่อบอกว่าหยุดตรงไหน</p><p>อ้างอิง: <a href="https://www.rfc-editor.org/rfc/rfc4271" target="_blank" rel="noopener">BGP / RFC 4271</a> · <a href="https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Web_mechanics/How_does_the_Internet_work" target="_blank" rel="noopener">Internet / MDN</a></p></section>`;}
export function initInternet(l,addScene,onComplete=()=>{}){
  const root=document.querySelector('.internet-lab'),stage=root.querySelector('.internet-stage'),range=root.querySelector('input[type=range]');let model,index=0,timer=null,scene=null,disposed=false;
  const legend=document.createElement('div');legend.className='internet-world-legend';legend.innerHTML='<span>สีเขียว · บ้าน / LAN</span><span>สีน้ำเงิน · ISP / Interconnection</span><span>สีม่วง · เครือข่ายบริการ</span>';stage.before(legend);
  const directory=document.createElement('details');directory.className='internet-directory';const summary=document.createElement('summary');summary.textContent='สำรวจอุปกรณ์และ IP ทั้ง 13 จุด';directory.append(summary);stage.after(directory);
  const stop=()=>{timer?.stop();timer=null;root.querySelector('[data-internet=play]').textContent='▶ เล่นเส้นทาง';};
  const draw=()=>{const f=model.steps[index],ev=root.querySelector('.internet-evidence');range.max=model.steps.length-1;range.value=index;ev.querySelector('p').textContent=`${index+1} / ${model.steps.length}`;ev.querySelector('h3').textContent=f.title;ev.querySelector('div').textContent=f.detail;ev.querySelector('dl').replaceChildren();for(const [k,v]of f.fields){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;row.append(dt,dd);ev.querySelector('dl').append(row);}ev.classList.toggle('problem',f.status==='blocked');stage.querySelector('.internet-fallback').textContent=f.transfers.map(t=>`${t.from} → ${t.to}: ${t.message}`).join('\n')||f.title;root.querySelector('[data-internet=prev]').disabled=index===0;root.querySelector('[data-internet=next]').disabled=index===model.steps.length-1;scene?.showStep(index);};
  const visited=new Set();const observe=()=>{visited.add(index);if(visited.size===model.steps.length&&model.steps.at(-1).status!=='blocked')onComplete();};
  const rebuild=()=>{stop();visited.clear();index=0;model=buildInternet(Object.fromEntries([...root.querySelectorAll('select')].map(el=>[el.name,el.value])));directory.querySelector('ul')?.remove();const list=document.createElement('ul');for(const n of model.nodes){const item=document.createElement('li');item.textContent=`${n.name} · ${n.address}`;list.append(item);}directory.append(list);scene?.setModel(model);draw();observe();};rebuild();
  root.querySelectorAll('select').forEach(el=>el.onchange=rebuild);range.oninput=()=>{stop();index=Number(range.value);draw();observe();};
  root.onclick=e=>{const action=e.target.closest('[data-internet]')?.dataset.internet;if(!action)return;if(action==='view'){scene?.resetView();return;}if(action==='play'){if(timer){stop();return;}if(index===model.steps.length-1)index=0;root.querySelector('[data-internet=play]').textContent='Ⅱ หยุด';draw();observe();timer=startFlowPlayback({scene:()=>scene,advance:()=>{index++;draw();observe();},atEnd:()=>index===model.steps.length-1,onEnd:stop,connected:()=>!disposed&&root.isConnected});return;}stop();index=action==='reset'?0:Math.max(0,Math.min(model.steps.length-1,index+(action==='next'?1:-1)));draw();observe();if(action==='reset')scene?.replay?.();};
  stage.addEventListener('mechanism-pick',e=>{const step=model.steps.findIndex(s=>s.active.includes(e.detail));if(step>=0){stop();index=step;draw();observe();}});
  addScene(stage,{mechanism:true,lesson:l,initialModel:model}).then(s=>{if(disposed){s?.dispose();return;}scene=s;if(s){stage.classList.add('has-webgl');s.setModel(model);s.showStep(index);}});
  return {dispose(){disposed=true;stop();}};
}
